mapper.select:
select mn.P_ID as pId, mn.P_Name as pName, mn.P_Project_Code as pProjectCode, mn.P_Code as pCode, mn.P_Construction_Unit as pConstructionUnit, c1.C_Name as pConstructionUnitName, mn.P_Use_Unit as pUseUnit, mn.P_Type as pType, mn.P_Create_Time as pCreateTime from Pre_Project mn left join SYS_Company c1 on mn.P_Construction_Unit=c1.C_ID ${params.authSql} and mn.P_Id in (select P_Id from Fund_Plan_Modify)
and mn.Te_Id = #{params.teId}
and likePname(#{params.pName},mn.P_ID)=true
and mn.P_Name like concat('%',#{params.pName},'%')
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.P_Create_Time DESC
limit #{params.start},#{params.size}

select count(*) from Pre_Project mn left join SYS_Company c1 on mn.P_Construction_Unit=c1.C_ID ${params.authSql} and mn.P_Id in (select P_Id from Fund_Plan_Modify)
and mn.Te_Id = #{params.teId}
and mn.P_Name like concat('%',#{params.pName},'%')

select pro.P_Name as pName, pro.P_Project_Code as pProjectCode, pro.P_Code as pCode, pro.P_Construction_Unit as pConstructionUnit, c1.C_Name as pConstructionUnitName, pro.P_Use_Unit as pUseUnit, c2.C_Name as pUseUnitName, pro.P_Type as pType,* from Fund_Plan_Modify mn left join Pre_Project pro on mn.P_Id=pro.P_Id left join SYS_Company c1 on pro.P_Construction_Unit=c1.C_ID left join SYS_Company c2 on pro.P_Use_Unit=c2.C_ID where mn.P_Id in
#{pId}
and mn.Fpm_Year in
#{fpmYear}
